import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 30 The death of a ghost","description":"学习 情态动词加完成式推断，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 30 The death of a ghost","description":"学习 情态动词加完成式推断，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 情态动词加完成式推断，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 29 Funny or not?","link":"/life/english/new-concept/book-3/unit-02/lesson-029"},"next":{"text":"第三册：培养技能 · Lesson 31 A lovable eccentric","link":"/life/english/new-concept/book-3/unit-02/lesson-031"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 29 Funny or not?","link":"/life/english/new-concept/book-3/unit-02/lesson-029"},"next":{"text":"第三册：培养技能 · Lesson 31 A lovable eccentric","link":"/life/english/new-concept/book-3/unit-02/lesson-031"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-030.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-030.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-030.md"};function l(s,e,r,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-30-the-death-of-a-ghost" tabindex="-1">第三册：培养技能 · Lesson 30 The death of a ghost <a class="header-anchor" href="#第三册-培养技能-·-lesson-30-the-death-of-a-ghost" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 30 The death of a ghost&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕奇怪现象与现实解释，练习对过去事件作有证据的推断。先列出声音、时间和物品变化，再给出可能解释，避免从一点线索跳到唯一结论。学习 must、may、can&#39;t 加完成式的确定程度，掌握推断与亲眼见到之间的区别。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>mystery</td><td>/ˈmɪstəri/</td><td>n.</td><td>谜团</td><td>solve a mystery</td></tr><tr><td>trace</td><td>/treɪs/</td><td>n.</td><td>痕迹</td><td>a trace of dust</td></tr><tr><td>hidden</td><td>/ˈhɪdn/</td><td>adj.</td><td>隐藏的</td><td>a hidden entrance</td></tr><tr><td>explanation</td><td>/ˌekspləˈneɪʃən/</td><td>n.</td><td>解释</td><td>a plausible explanation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>account for — 解释现象的原因</li><li>rule out — 排除一种可能</li></ul><h2 id="语法讲解-情态动词加完成式推断" tabindex="-1">语法讲解：情态动词加完成式推断 <a class="header-anchor" href="#语法讲解-情态动词加完成式推断" aria-label="Permalink to &quot;语法讲解：情态动词加完成式推断&quot;">​</a></h2><p>must have done 表示根据现有线索对过去作较强肯定推断，may 或 might have done 表示可能，can&#39;t 或 couldn&#39;t have done 常表示不可能。它们都不是简单的过去义务；“过去必须做”通常用 had to do。否定推断也应有足够依据，未看见不代表不可能。情态完成式中的 have 用原形，后接过去分词，主语单复数不改变这一结构。写悬疑解释时可以先使用较弱推断，再随着证据增加调整措辞。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Someone must have opened the cupboard, because the flour had been moved.</p></blockquote><p>一定有人打开过橱柜，因为面粉被移动过了。</p><p>must have opened 是基于线索的推断，because 从句给出依据；推断仍不同于亲眼观察。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He must opened 错缺 have；He had to open 表示过去不得不打开，意义不是过去推断。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比读 must have opened、might have opened、can&#39;t have opened，把情态动词读清；让录音中的确定程度可辨。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The noise began when the wind rose. A loose shutter may have struck the wall. We will examine the hinges in daylight.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为夜间怪声写三句解释，包含线索、可能性和下一步检查。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先报告同时发生的现象，再提出可检验假设，避免把相关性直接当作证明。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句是否声称说话者亲眼看见开柜子？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> because 引出间接证据。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>将“可能忘了锁门”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> may have forgotten to lock the door</p><p><strong>解析：</strong> may have done 表示对过去的可能推断。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：It can&#39;t have ___ through this tiny gap.（passed/pass）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> passed</p><p><strong>解析：</strong> have 后用过去分词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词加完成式推断。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-029">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-031">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
